7	import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
8	import * as fs from 'node:fs';
9	import * as path from 'node:path';
10	import * as os from 'node:os';
11	import type { Config } from '../config/config.js';
12	import { createMockWorkspaceContext } from '../test-utils/mockWorkspaceContext.js';
13	import { FileDiscoveryService } from '../services/fileDiscoveryService.js';
14	import { correctPath } from './pathCorrector.js';
15	
16	describe('pathCorrector', () => {
17	  let tempDir: string;
18	  let rootDir: string;
19	  let otherWorkspaceDir: string;
20	  let mockConfig: Config;
21	
22	  beforeEach(() => {
23	    tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'path-corrector-test-'));
24	    rootDir = path.join(tempDir, 'root');
25	    otherWorkspaceDir = path.join(tempDir, 'other');
26	    fs.mkdirSync(rootDir, { recursive: true });
27	    fs.mkdirSync(otherWorkspaceDir, { recursive: true });
28	
29	    mockConfig = {
30	      getTargetDir: () => rootDir,
31	      getWorkspaceContext: () =>
32	        createMockWorkspaceContext(rootDir, [otherWorkspaceDir]),
33	      getFileService: () => new FileDiscoveryService(rootDir),
34	      getFileFilteringOptions: () => ({
35	        respectGitIgnore: true,
36	        respectGeminiIgnore: true,
37	      }),
38	    } as unknown as Config;
39	  });
40	
41	  afterEach(() => {
42	    fs.rmSync(tempDir, { recursive: true, force: true });
43	    vi.restoreAllMocks();
44	  });
45	
46	  it('should correct a relative path if it is unambiguous in the target dir', () => {
47	    const testFile = 'unique.txt';
48	    fs.writeFileSync(path.join(rootDir, testFile), 'content');
49	
50	    const result = correctPath(testFile, mockConfig);
51	
52	    expect(result.success).toBe(true);
53	    if (result.success) {
54	      expect(result.correctedPath).toBe(path.join(rootDir, testFile));
55	    }
56	  });
57	
58	  it('should correct a partial relative path if it is unambiguous in another workspace dir', () => {
59	    const subDir = path.join(otherWorkspaceDir, 'sub');
60	    fs.mkdirSync(subDir);
61	    const testFile = 'file.txt';
62	    const fullPath = path.join(subDir, testFile);
63	    fs.writeFileSync(fullPath, 'content');
64	
65	    const result = correctPath(testFile, mockConfig);
66	
67	    expect(result.success).toBe(true);
68	    if (result.success) {
69	      expect(result.correctedPath).toBe(fullPath);
70	    }
71	  });
72	
73	  it('should return an error for a relative path that does not exist', () => {
74	    const result = correctPath('nonexistent.txt', mockConfig);
75	    expect(result.success).toBe(false);
76	    if (!result.success) {
77	      expect(result.error).toMatch(
78	        /File not found for 'nonexistent.txt' and path is not absolute./,
79	      );
80	    } else {
81	      expect.fail('Expected path correction to fail.');
82	    }
83	  });
84	
85	  it('should return an error for an ambiguous path', () => {
86	    const ambiguousFile = 'component.ts';
87	    const subDir1 = path.join(rootDir, 'module1');
88	    const subDir2 = path.join(otherWorkspaceDir, 'module2');
89	    fs.mkdirSync(subDir1, { recursive: true });
90	    fs.mkdirSync(subDir2, { recursive: true });
91	    fs.writeFileSync(path.join(subDir1, ambiguousFile), 'content 1');
92	    fs.writeFileSync(path.join(subDir2, ambiguousFile), 'content 2');
93	
94	    const result = correctPath(ambiguousFile, mockConfig);
95	
96	    expect(result.success).toBe(false);
97	    if (!result.success) {
98	      expect(result.error).toMatch(
99	        /The file path 'component.ts' is ambiguous and matches multiple files./,
100	      );
101	    } else {
102	      expect.fail('Expected path correction to fail.');
103	    }
104	  });
105	});
