23	/**
24	 * Attempts to correct a relative or ambiguous file path to a single, absolute path
25	 * within the workspace.
26	 *
27	 * @param filePath The file path to correct.
28	 * @param config The application configuration.
29	 * @returns A `PathCorrectionResult` object with either a `correctedPath` or an `error`.
30	 */
31	export type PathCorrectionResult =
32	  | SuccessfulPathCorrection
33	  | FailedPathCorrection;
34	export function correctPath(
35	  filePath: string,
36	  config: Config,
37	): PathCorrectionResult {
38	  const sanitizedPath = resolveDefensiveToolPath(
39	    filePath,
40	    config.getTargetDir(),
41	  );
42	
43	  // Check for direct path relative to the primary target directory.
44	  const directPath = path.join(config.getTargetDir(), sanitizedPath);
45	  if (fs.existsSync(directPath)) {
46	    return { success: true, correctedPath: directPath };
47	  }
48	
49	  // If not found directly, search across all workspace directories for ambiguous matches.
50	  const workspaceContext = config.getWorkspaceContext();
51	  const searchPaths = workspaceContext.getDirectories();
52	  const basename = path.basename(sanitizedPath);
53	  const normalizedTarget = sanitizedPath.replace(/\\/g, '/');
54	
55	  // Normalize path for matching and check if it ends with the provided relative path
56	  const foundFiles = searchPaths
57	    .flatMap((searchPath) =>
58	      bfsFileSearchSync(searchPath, {
59	        fileName: basename,
60	        maxDirs: 50, // Capped to avoid deep hangs
61	        fileService: config.getFileService(),
62	        fileFilteringOptions: config.getFileFilteringOptions(),
63	      }),
64	    )
65	    .filter((f) => f.replace(/\\/g, '/').endsWith(normalizedTarget));
66	
67	  if (foundFiles.length === 0) {
68	    return {
69	      success: false,
70	      error: `File not found for '${filePath}' and path is not absolute.`,
71	    };
72	  }
73	
74	  if (foundFiles.length > 1) {
75	    return {
76	      success: false,
77	      error: `The file path '${filePath}' is ambiguous and matches multiple files. Please provide a more specific path. Matches: ${foundFiles.join(', ')}`,
78	    };
79	  }
80	
81	  return { success: true, correctedPath: foundFiles[0] };
