576	/**
577	 * Defensively resolves and sanitizes a file path generated by the LLM,
578	 * stripping user-facing reference prefixes if necessary.
579	 */
580	export function resolveDefensiveToolPath(
581	  filePath: string,
582	  targetDir: string,
583	): string {
584	  const cleanPath = filePath.replace(/\0/g, '');
585	
586	  try {
587	    const literalPath = path.resolve(targetDir, cleanPath);
588	
589	    // If the file literally exists on disk as-is, return the resolved literal path immediately
590	    if (fs.existsSync(literalPath)) {
591	      return cleanPath;
592	    }
593	
594	    // If the model supplied a leading @ prefix and the literal path doesn't exist:
595	    if (cleanPath.startsWith('@') && cleanPath.length > 1) {
596	      if (cleanPath.startsWith('@/') || cleanPath.startsWith('@\\')) {
597	        const stripped = cleanPath.substring(1).replace(/^[\\/]+/, '');
598	        return stripped.length > 0 ? stripped : cleanPath;
599	      }
600	
601	      const strippedPath = cleanPath.substring(1).replace(/^[\\/]+/, '');
602	
603	      // Check if a literal directory/file starting with '@' exists for the first segment.
604	      // If it does, we should preserve the '@' prefix.
605	      const parts = strippedPath.split(/[\\/]/);
606	      const firstSegment = parts[0];
607	      if (firstSegment) {
608	        const literalFirstSegment = path.resolve(targetDir, '@' + firstSegment);
609	        if (fs.existsSync(literalFirstSegment)) {
610	          return cleanPath;
611	        }
612	
613	        // Otherwise, strip the '@' prefix to resolve to the standard directory name,
614	        // preventing the accidental creation of literal '@'-prefixed directories (e.g. '@src', '@policies')
615	        // when creating new files or directories.
616	        return strippedPath;
617	      }
618	    }
619	  } catch {
620	    // Fallback to original path if any filesystem or resolution error occurs
621	  }
622	
623	  // Fallback: return the original path
624	  return cleanPath;
625	}

