107	export async function getCorrectedFileContent(
108	  config: Config,
109	  filePath: string,
110	  proposedContent: string,
111	  abortSignal: AbortSignal,
112	): Promise<GetCorrectedFileContentResult> {
113	  let originalContent = '';
114	  let fileExists = false;
115	  let correctedContent = proposedContent;
116	
117	  let resolvedPath: string;
118	  if (config.isPlanMode()) {
119	    try {
120	      const cleanFilePath = filePath.replace(/\0/g, '');
121	      const planPath = resolveAndValidatePlanPath(
122	        cleanFilePath,
123	        config.storage.getPlansDir(),
124	        config.getProjectRoot(),
125	      );
126	      resolvedPath = resolveToRealPath(planPath);
127	    } catch (err) {
128	      return {
129	        originalContent: '',
130	        correctedContent: proposedContent,
131	        fileExists: false,
132	        error: {
133	          message:
134	            'Failed to resolve plan path: ' +
135	            (err instanceof Error ? err.message : String(err)),
136	          code: 'EINVAL',
137	        },
138	      };
139	    }
140	  } else {
141	    const sanitizedPath = resolveDefensiveToolPath(
142	      filePath,
143	      config.getTargetDir(),
144	    );
145	    try {
146	      resolvedPath = resolveToRealPath(
147	        path.resolve(config.getTargetDir(), sanitizedPath),
148	      );
149	    } catch (err) {
150	      return {
151	        originalContent: '',
152	        correctedContent: proposedContent,
153	        fileExists: false,
154	        error: {
155	          message:
156	            'Failed to resolve path: ' +
157	            (err instanceof Error ? err.message : String(err)),
158	          code: 'EINVAL',
159	        },
160	      };
161	    }
162	  }
163	
164	  const validationError = config.validatePathAccess(resolvedPath);
165	  if (validationError) {
166	    return {
167	      originalContent: '',
168	      correctedContent: proposedContent,
169	      fileExists: false,
170	      error: { message: validationError, code: 'EACCES' },
171	    };
172	  }
173	
174	  try {
175	    originalContent = await config
176	      .getFileSystemService()
177	      .readTextFile(resolvedPath);
178	    fileExists = true; // File exists and was read
179	  } catch (err) {
180	    if (isNodeError(err) && err.code === 'ENOENT') {
181	      fileExists = false;
182	      originalContent = '';
183	    } else {
184	      // File exists but could not be read (permissions, etc.)
185	      fileExists = true; // Mark as existing but problematic
186	      originalContent = ''; // Can't use its content
187	      const error = {
188	        message: getErrorMessage(err),
189	        code: isNodeError(err) ? err.code : undefined,
190	      };
191	      // Return early as we can't proceed with content correction meaningfully
192	      return { originalContent, correctedContent, fileExists, error };
193	    }
194	  }
195	
196	  const aggressiveUnescape = !isGemini3Model(config.getActiveModel());
197	
198	  correctedContent = await ensureCorrectFileContent(
199	    proposedContent,
200	    config.getBaseLlmClient(),
201	    abortSignal,
202	    config.getDisableLLMCorrection(),
203	    aggressiveUnescape,
204	  );
205	
206	  return { originalContent, correctedContent, fileExists };
207	}
